/** Literal token search; player text is never interpreted as a regular expression. */
export function searchFieldGuide(query,options={}) {
 const topics=fieldGuideTopics(options),tokens=normalize(query).split(' ').filter(token=>token&&!searchFillers.has(token)).slice(0,20);
 if(!tokens.length)return topics;
 return topics.map((topic,index)=>{
  const title=normalize(topic.title),tags=normalize(topic.tags.join(' ')),body=normalize([topic.summary,...topic.steps,topic.why,...topic.blockers].join(' '));
  if(!tokens.every(token=>title.includes(token)||tags.includes(token)||body.includes(token)))return null;
  const score=tokens.reduce((sum,token)=>sum+(title.includes(token)?6:0)+(tags.includes(token)?3:0)+(body.includes(token)?1:0),0);
  return{topic,score,index};
 }).filter(Boolean).sort((a,b)=>b.score-a.score||a.index-b.index).map(result=>result.topic);
}

/** Context recommendations are topic IDs; no hidden actors or live locations are read. */
export function recommendFieldGuideTopics(context={}, {limit=3}={}) {
 const ids=[],add=(...values)=>{for(const id of values)if(!ids.includes(id))ids.push(id);};
 const branch=context.military?.branchId||context.military?.branch?.id||context.branchId;
 if(context.recovery&&!context.recovery.arrived||context.detained)add('recovery','passage');
 if(context.gunnery===true||context.gunnery?.active)add('gunnery','navy');
 if(context.boarding)add('personal-combat','docking');
 if(context.combat?.active)add('personal-combat','exploration');
 if(context.military?.active||context.military?.enlisted||branch)add(branch==='army'?'army':branch==='navy'?'navy':'military','military-together','military');
 if(context.shared||context.sharedGalaxy||context.multiplayer||context.online)add('play-together','ship-permissions');
 if(context.crewDuty||context.npcContract?.active)add('crew-duty');
 if(context.hasShip===false||context.ownsShip===false)add('passage','work');
 if(context.job?.accepted||context.job?.ready||context.nearby?.type==='jobboard'||context.nearby?.type==='work')add('work');
 if(context.surfaceKind==='site'||context.exploration)add('exploration','personal-combat');
 if(context.surfaceKind==='ship'||context.helm?.available)add('docking','ship-permissions');
 if(context.docking)add('docking','flight');
 if(context.mode==='ship')add(context.ship?.threat?'ship-combat':'flight','navigation','mining');
 else if(context.mode==='person')add('walking','navigation','first-steps');
 else add('first-steps','play-together','screen-controls');
 const count=Math.max(1,Math.min(6,Number.isFinite(Number(limit))?Math.floor(Number(limit)):3));
 return ids.slice(0,count);
}
